def clean(df):
    df = df.copy()
    # Fix Region label variants
    region_map = {
        'west': 'West', 'south': 'South', 'Wst': 'West', 'Suoth': 'South'
    }
    df['Region'] = df['Region'].replace(region_map)
    # Fix Quantity: negative values are invalid (min=1)
    df.loc[df['Quantity'] < 1, 'Quantity'] = pd.NA
    return df

def answer(df):
    df = clean(df)
    # Drop rows with missing Region or Quantity
    df = df.dropna(subset=['Region', 'Quantity'])
    result = df.groupby('Region')['Quantity'].sum().to_dict()
    return {str(k): int(v) for k, v in result.items()}
